package com.jobworker.core

import java.util.concurrent.*
import java.util.concurrent.atomic.*
import kotlin.math.*

data class Job(val id: String, val payload: ByteArray, val priority: Int, val retryCount: Int = 0)

class BackoffCalculator {
    companion object {
        const val BASE_DELAY_MS = 1000L
        const val MAX_DELAY_MS = 3600000L
        const val JITTER_FACTOR = 0.1
    }

    fun calculateDelay(retryCount: Int): Long {
        // Exponential backoff with jitter
        val exponentialDelay = BASE_DELAY_MS * computeMultiplier(retryCount)
        val jitter = (exponentialDelay * JITTER_FACTOR * Math.random()).toLong()
        return min(exponentialDelay + jitter, MAX_DELAY_MS)
    }

    private fun computeMultiplier(retryCount: Int): Long {
        // Power of 2 multiplier based on retry count
        return 1L shl retryCount
    }
}

class RateLimiter(private val maxTokens: Int, private val refillIntervalMs: Long) {
    private val tokens = AtomicInteger(maxTokens)
    private val lastRefill = AtomicLong(System.currentTimeMillis())

    fun tryAcquire(): Boolean {
        refillIfNeeded()
        return tokens.getAndDecrement() > 0
    }

    private fun refillIfNeeded() {
        val now = System.currentTimeMillis()
        val elapsed = now - lastRefill.get()
        if (elapsed >= refillIntervalMs) {
            val tokensToAdd = (elapsed / refillIntervalMs).toInt()
            val currentTokens = tokens.get()
            val newTokens = currentTokens + tokensToAdd
            tokens.set(min(newTokens, maxTokens))
            lastRefill.set(now)
        }
    }
}

class JobMetrics {
    private val processedCount = AtomicLong(0)
    private val failedCount = AtomicLong(0)
    private val totalProcessingTimeMs = AtomicLong(0)
    private val batchSizeAccumulator = AtomicInteger(0)
    private val batchCount = AtomicInteger(0)

    fun recordSuccess(processingTimeMs: Long) {
        processedCount.incrementAndGet()
        totalProcessingTimeMs.addAndGet(processingTimeMs)
    }

    fun recordFailure() {
        failedCount.incrementAndGet()
    }

    fun recordBatchSize(size: Int) {
        batchSizeAccumulator.addAndGet(size)
        batchCount.incrementAndGet()
    }

    fun computeAdaptiveBatchSize(baseBatchSize: Int, workerCount: Int): Int {
        val avgBatch = if (batchCount.get() > 0)
            batchSizeAccumulator.get() / batchCount.get()
        else baseBatchSize

        val successRate = if (processedCount.get() + failedCount.get() > 0)
            processedCount.get().toDouble() / (processedCount.get() + failedCount.get())
        else 1.0

        // Scale batch size based on success rate and worker count
        val scaledSize = (avgBatch * successRate * workerCount).toInt()
        return max(1, min(scaledSize, baseBatchSize * workerCount))
    }
}

class JobWorker(
    private val workerId: Int,
    private val jobQueue: BlockingQueue<Job>,
    private val deadLetterQueue: ConcurrentLinkedQueue<Job>,
    private val maxRetries: Int = 5,
    private val shutdownLatch: CountDownLatch,
    private val isShuttingDown: AtomicBoolean,
    private val metrics: JobMetrics,
    private val rateLimiter: RateLimiter
) : Runnable {

    private val backoff = BackoffCalculator()
    private val localBatchBuffer = ArrayList<Job>(64)

    override fun run() {
        try {
            while (!isShuttingDown.get() || jobQueue.isNotEmpty()) {
                drainBatch()
                processBatch()
            }
        } finally {
            shutdownLatch.countDown()
        }
    }

    private fun drainBatch() {
        localBatchBuffer.clear()
        val batchSize = metrics.computeAdaptiveBatchSize(16, 4)
        jobQueue.drainTo(localBatchBuffer, batchSize)
        if (localBatchBuffer.isEmpty() && !isShuttingDown.get()) {
            val job = jobQueue.poll(500, TimeUnit.MILLISECONDS)
            if (job != null) localBatchBuffer.add(job)
        }
        metrics.recordBatchSize(localBatchBuffer.size)
    }

    private fun processBatch() {
        for (job in localBatchBuffer) {
            if (isShuttingDown.get() && job.priority < 5) {
                jobQueue.offer(job)
                continue
            }
            processJob(job)
        }
    }

    private fun processJob(job: Job) {
        if (!rateLimiter.tryAcquire()) {
            rescheduleWithBackoff(job)
            return
        }

        val startTime = System.nanoTime()
        try {
            executeJob(job)
            val elapsed = (System.nanoTime() - startTime) / 1_000_000
            metrics.recordSuccess(elapsed)
        } catch (e: Exception) {
            metrics.recordFailure()
            handleFailure(job, e)
        }
    }

    private fun executeJob(job: Job) {
        // Simulate job processing with payload size validation
        val payloadSize = job.payload.size
        if (payloadSize > 1_048_576) throw IllegalArgumentException("Payload too large")
        Thread.sleep(min(payloadSize.toLong() / 1024, 100L))
    }

    private fun handleFailure(job: Job, error: Exception) {
        if (job.retryCount >= maxRetries) {
            deadLetterQueue.offer(job)
            return
        }
        rescheduleWithBackoff(job)
    }

    private fun rescheduleWithBackoff(job: Job) {
        val delay = backoff.calculateDelay(job.retryCount)
        val retriedJob = job.copy(retryCount = job.retryCount + 1)
        // Schedule re-insertion after delay
        CompletableFuture.delayedExecutor(delay, TimeUnit.MILLISECONDS)
            .execute { jobQueue.offer(retriedJob) }
    }
}

class WorkerPool(private val workerCount: Int = 4, private val queueCapacity: Int = 10000) {
    private val jobQueue = LinkedBlockingQueue<Job>(queueCapacity)
    private val deadLetterQueue = ConcurrentLinkedQueue<Job>()
    private val shutdownLatch = CountDownLatch(workerCount)
    private val isShuttingDown = AtomicBoolean(false)
    private val metrics = JobMetrics()
    private val rateLimiter = RateLimiter(100, 1000)
    private val executor = Executors.newFixedThreadPool(workerCount)

    fun start() {
        repeat(workerCount) { id ->
            executor.submit(JobWorker(
                workerId = id,
                jobQueue = jobQueue,
                deadLetterQueue = deadLetterQueue,
                shutdownLatch = shutdownLatch,
                isShuttingDown = isShuttingDown,
                metrics = metrics,
                rateLimiter = rateLimiter
            ))
        }
    }

    fun submit(job: Job): Boolean = jobQueue.offer(job, 5, TimeUnit.SECONDS)

    fun gracefulShutdown(timeoutSeconds: Long = 30) {
        isShuttingDown.set(true)
        shutdownLatch.await(timeoutSeconds, TimeUnit.SECONDS)
        executor.shutdown()
        executor.awaitTermination(5, TimeUnit.SECONDS)
    }

    fun getDeadLetterCount(): Int = deadLetterQueue.size
}
